          <div class="space-y-1">
            <label for="branch-sel" class="text-[9px] font-bold text-slate-500 uppercase">Branch / Target</label>
            <select id="branch-sel" onchange="selectBranch(this.value)" class="w-full bg-slate-950 border border-slate-800 rounded-lg px-2.5 py-1.5 text-xs text-slate-200 font-mono focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500 transition-[border-color,box-shadow] duration-200" ${jf!=="github-remote"?"disabled":""}>
              ${jf==="local-server"?'<option value="local">\u{1F5A5}\uFE0F local (live filesystem)</option>':jf==="local-folder"?`<option value="local">\u{1F4C1} local (${AE||"directory"})</option>`:gT.map(N=>`<option value="${N}" ${N===ap?"selected":""}>${N}</option>`).join("")}
            </select>
          </div>

